# Node 12. The last pure check before anything is written. Fails closed:
# every unknown is a block, never a pass.
blocked_by = []

if not input.get("users_ok"):
    blocked_by.append("user validation did not pass")

plan = input.get("plan") or {}
if not plan.get("ok"):
    blocked_by.append("no plan output to act on")
elif not plan.get("total"):
    blocked_by.append("the plan matched no records")

if not input.get("risk_ok"):
    blocked_by.append("the risk join did not complete")

level = input.get("level")
if level not in ("routine", "elevated", "dual_control"):
    blocked_by.append("approval tier is missing or unrecognised (" + str(level) + ")")

# plan_handover fingerprints the set internally and apply_handover re-reads and
# re-hashes it, refusing on drift. The fingerprint is not in the plan OUTPUT,
# so this node cannot check it - the module enforces that itself, at apply.
output = {
    "proceed": not blocked_by,
    "blocked_by": blocked_by,
    "drift_check": "enforced inside apply_handover, not here - the plan "
                   "fingerprint is not exposed in the plan output",
}

# Node 17. The run refusing to call itself finished while something is
# unaccounted for - the module's own refusal behaviour, at the run level.
#
# Parented to `guard` rather than to the evidence chain on purpose. A skipped
# node's children are skipped too, so parenting this to `custody` would mean
# the one node whose job is to report "held, and here is why" never runs on
# precisely the runs that were held. Every binding below can therefore be None.
held = []

if not input.get("guard_proceed"):
    for reason in (input.get("blocked") or ["the guard blocked this run"]):
        held.append(str(reason))

applied = input.get("apply") or {}
reconcile = input.get("reconcile") or {}
verify = input.get("verify") or {}
custody = input.get("custody") or {}

if applied.get("ok"):
    if applied.get("failed"):
        held.append(str(applied.get("failed")) + " reassignment(s) were rejected by Zoho")

    if not reconcile.get("ok"):
        held.append("reconcile_writes did not report")
    elif reconcile.get("unknown"):
        held.append(str(reconcile.get("unknown")) + " write(s) still have an outcome nobody can determine")

    if not verify.get("ok"):
        held.append("verify_ledger did not report")
    elif not verify.get("intact"):
        held.append("the ledger chain is broken at entry " + str(verify.get("first_broken_entry")))

    if not custody.get("ok"):
        held.append("custody_report did not report")
    elif custody.get("diverged"):
        held.append(str(custody.get("diverged")) + " Leads record(s) came back diverged after the handover")

settled = not held
if settled and not applied.get("ok"):
    settled = False
    held.append("no handover was applied in this run")

if settled:
    summary = ("Settled. " + str(applied.get("moved") or 0) + " records moved, "
               "ledger chain intact, every write accounted for, no Leads record diverged.")
else:
    summary = "Held: " + "; ".join(held)

output = {
    "settled": settled,
    "held_because": held,
    "summary": summary,
    "covers": "settlement is judged over what this run can see: reconcile "
              "verdicts, the ledger chain, and custody verdicts for Leads. "
              "Contacts, Accounts and Deals are covered by the ledger check "
              "only.",
}
